"""Tests for the commission-calculator Step 4 math.

Anchored to the worked "Example 1" in the SKILL where its numbers follow the
stated formula (per-sale commission and month-1 earnings), plus the formula's
own deterministic outputs for recurring compounding and one-time rewards.
"""

import math

import pytest

import commission_calculator as cc


# ---- reward parsing -------------------------------------------------------

def test_parse_percentage():
    assert cc.parse_reward_value("30%") == (30.0, True)


def test_parse_fixed_dollar():
    assert cc.parse_reward_value("$50") == (50.0, False)


def test_parse_bare_number_is_fixed():
    assert cc.parse_reward_value(50) == (50.0, False)


# ---- commission per sale --------------------------------------------------

def test_commission_per_sale_percentage_matches_skill_example1():
    # SKILL Example 1: HeyGen 30% recurring, $39 avg plan -> $11.70/conversion
    heygen = {"name": "HeyGen", "reward_value": "30%",
              "reward_type": "cps_recurring", "avg_product_price": 39}
    assert cc.commission_per_sale(heygen) == pytest.approx(11.70)


def test_commission_per_sale_fixed():
    prog = {"reward_value": "$50", "reward_type": "cps_one_time"}
    assert cc.commission_per_sale(prog) == pytest.approx(50.0)


def test_percentage_without_price_raises():
    prog = {"name": "X", "reward_value": "30%", "reward_type": "cps_recurring"}
    with pytest.raises(ValueError):
        cc.commission_per_sale(prog)


# ---- funnel ---------------------------------------------------------------

def test_monthly_conversions_matches_skill_example1():
    # 5,000 visitors x 3% CTR x 3% conversion = 4.5 sales/mo
    assert cc.monthly_conversions(5000, 0.03, 0.03) == pytest.approx(4.5)


# ---- recurring compounding ------------------------------------------------

def test_recurring_month1_matches_skill_example1():
    heygen = {"name": "HeyGen", "reward_value": "30%",
              "reward_type": "cps_recurring", "avg_product_price": 39}
    series = cc.monthly_revenue_series(heygen, 4.5, months=12)
    # Month 1: 4.5 conversions x $11.70 = $52.65 (matches SKILL example)
    assert series[0] == pytest.approx(52.65)


def test_recurring_lifetime_compounds_linearly():
    heygen = {"name": "HeyGen", "reward_value": "30%",
              "reward_type": "cps_recurring", "avg_product_price": 39}
    series = cc.monthly_revenue_series(heygen, 4.5, months=12)
    cps = 11.70
    # lifetime: month N active subscribers = N * conversions
    for n in range(1, 13):
        assert series[n - 1] == pytest.approx(n * 4.5 * cps)


def test_recurring_capped_by_duration():
    prog = {"reward_value": "$10", "reward_type": "cps_recurring",
            "reward_duration": "3 months"}
    series = cc.monthly_revenue_series(prog, 2, months=6)
    # active cohorts plateau at min(month, 3): 1,2,3,3,3,3 cohorts of 2 subs @ $10
    expected = [c * 2 * 10 for c in [1, 2, 3, 3, 3, 3]]
    assert series == pytest.approx(expected)


def test_first_purchase_duration_is_one_month():
    prog = {"reward_value": "$10", "reward_type": "cps_recurring",
            "reward_duration": "first purchase"}
    series = cc.monthly_revenue_series(prog, 2, months=4)
    assert series == pytest.approx([20, 20, 20, 20])


# ---- one-time -------------------------------------------------------------

def test_one_time_does_not_compound():
    prog = {"reward_value": "$50", "reward_type": "cps_one_time"}
    series = cc.monthly_revenue_series(prog, 3, months=4)
    assert series == pytest.approx([150, 150, 150, 150])


# ---- projection dict ------------------------------------------------------

def test_project_program_shape_and_values():
    heygen = {"name": "HeyGen", "reward_value": "30%",
              "reward_type": "cps_recurring", "avg_product_price": 39}
    proj = cc.project_program(heygen, 4.5, months=12)
    assert proj["program_name"] == "HeyGen"
    assert proj["reward_type"] == "cps_recurring"
    assert proj["commission_per_sale"] == pytest.approx(11.70)
    assert proj["monthly_30d"] == pytest.approx(52.65)
    assert proj["monthly_90d"] == pytest.approx(3 * 4.5 * 11.70)
    assert proj["monthly_12m"] == pytest.approx(12 * 4.5 * 11.70)
    # cumulative = cps * conversions * (1+2+...+12) = 52.65 * 78
    assert proj["cumulative_12m"] == pytest.approx(52.65 * 78)


# ---- reverse calculation --------------------------------------------------

def test_sales_needed_for_goal():
    assert cc.sales_needed_for_goal(500, 11.70) == pytest.approx(500 / 11.70)


def test_visitors_needed_for_goal():
    # need `sales` conversions; each visitor converts at ctr*cr
    v = cc.visitors_needed_for_goal(500, 11.70, 0.03, 0.03)
    assert v == pytest.approx((500 / 11.70) / (0.03 * 0.03))


def test_unknown_reward_type_raises():
    prog = {"reward_value": "$10", "reward_type": "mystery"}
    with pytest.raises(ValueError):
        cc.monthly_revenue_series(prog, 1, months=1)


def test_lifetime_duration_is_infinite():
    prog = {"reward_value": "$10", "reward_type": "cps_recurring",
            "reward_duration": "lifetime"}
    assert cc._duration_months(prog) == math.inf
